// ── Control flow ──

function lowerIf_ad(ctx, node) {
  return lowerIfRegion(ctx,
    () => lowerExpr_ad(ctx, node.test),
    () => { for (const s of node.body) lowerStmt_ad(ctx, s); },
    () => { if (node.orelse) for (const s of node.orelse) lowerStmt_ad(ctx, s); },
    ctx.loc(node));
}

